import { useState, useEffect } from "react";
import axios from "axios";

export const FALLBACK_DATA = {
  Apenom: "GUTIERREZ ROLDAN JEREMIAS",
  Fechanac: "14/02/2003",
  Ciudad: "Mar del Plata",
  Nafiliado: "785-311234/0",
  Badocnumdo: "44.892.124",
  Parentesco: "Titular",
  Categoria: "Activo",
  Plan: "Plan Azul",
  Vencimiento: "12/2026",
};

export const data = () => {
  const [list, setList] = useState(FALLBACK_DATA);

  useEffect(() => {
    let isMounted = true;
    axios({
      url: "http://google.com",
      timeout: 3000,
    })
      .then((response) => {
        if (isMounted && response?.data && typeof response.data === "object") {
          setList({
            ...FALLBACK_DATA,
            ...response.data,
          });
        }
      })
      .catch(() => {
        // Fallback garantizado en caso de offline, CORS o error del servidor
        if (isMounted) {
          setList(FALLBACK_DATA);
        }
      });

    return () => {
      isMounted = false;
    };
  }, []);

  return list;
};
