import React, { useRef, useState } from "react";
import {
  View,
  Text,
  TouchableOpacity,
  ImageBackground,
  Animated,
  StyleSheet,
  Platform,
} from "react-native";
import { MaterialCommunityIcons, Feather } from "@expo/vector-icons";
import { estilo } from "../Screens/Perfil/StyleSheetInicio.jsx";
import { data } from "../Funciones/apiRequest.js";
import { LogoText } from "./LogoText.jsx";
import { FirmaText } from "./FirmaText.jsx";
import { Sellos } from "./Sellos.jsx";

export function ScreenTarjetaAzul() {
  const obj = data();
  const [esDorso, setEsDorso] = useState(false);

  // Valor animado de 0 a 180 grados
  const animacionGiro = useRef(new Animated.Value(0)).current;

  const voltearTarjeta = () => {
    if (esDorso) {
      Animated.spring(animacionGiro, {
        toValue: 0,
        friction: 8,
        tension: 10,
        useNativeDriver: Platform.OS !== "web", // En web Animated transform funciona fluidamente
      }).start();
      setEsDorso(false);
    } else {
      Animated.spring(animacionGiro, {
        toValue: 180,
        friction: 8,
        tension: 10,
        useNativeDriver: Platform.OS !== "web",
      }).start();
      setEsDorso(true);
    }
  };

  // Interpolación de la rotación para el frente
  const rotacionFrente = animacionGiro.interpolate({
    inputRange: [0, 180],
    outputRange: ["0deg", "180deg"],
  });

  // Interpolación de la rotación para el dorso
  const rotacionDorso = animacionGiro.interpolate({
    inputRange: [0, 180],
    outputRange: ["180deg", "360deg"],
  });

  // Opacidad cruzada para evitar parpadeos en renderers web y móvil
  const opacidadFrente = animacionGiro.interpolate({
    inputRange: [89, 90],
    outputRange: [1, 0],
  });

  const opacidadDorso = animacionGiro.interpolate({
    inputRange: [89, 90],
    outputRange: [0, 1],
  });

  if (!obj) return null;

  return (
    <View style={flipStyles.contenedorPrincipal}>
      <TouchableOpacity
        activeOpacity={0.95}
        onPress={voltearTarjeta}
        style={estilo.cardWrapper}
      >
        {/* --- CARA FRONTAL --- */}
        <Animated.View
          style={[
            estilo.cardFace,
            {
              transform: [{ perspective: 1000 }, { rotateY: rotacionFrente }],
              opacity: opacidadFrente,
              backfaceVisibility: "hidden",
            },
          ]}
        >
          <ImageBackground
            source={require("../Imagenes/fondo.png")}
            resizeMode="cover"
            style={estilo.backgroundImage}
            imageStyle={{ borderRadius: 16 }}
          >
            <View style={estilo.cardInner}>
              {/* Header con Logo y Título OSEM */}
              <View style={estilo.header}>
                <LogoText />
                <View style={estilo.headerRight}>
                  <Text style={estilo.osemTitulo}>OSEM</Text>
                  <Text style={estilo.osemSubTitulo}>GNRAL PUEYRREDON</Text>
                </View>
              </View>

              {/* Línea divisoria */}
              <View style={estilo.divisor} />

              {/* Nombre completo del Afiliado */}
              <Text style={estilo.nombreSocio}>
                {obj.Apenom || "GUTIERREZ ROLDAN JEREMIAS"}
              </Text>

              {/* Grilla de datos organizada por columnas */}
              <View style={estilo.infoGrid}>
                <View style={estilo.infoRow}>
                  <View style={estilo.columna}>
                    <Text style={estilo.valor}>{obj.Fechanac || "14/02/2003"}</Text>
                    <Text style={estilo.etiqueta}>Fecha Nac.</Text>
                  </View>
                  <View style={estilo.columna}>
                    <Text style={estilo.valor}>{obj.Ciudad || "Mar del Plata"}</Text>
                    <Text style={estilo.etiqueta}>Ciudad</Text>
                  </View>
                  <View style={estilo.columna}>
                    <Text style={estilo.valor}>{obj.Nafiliado || "785-311234"}</Text>
                    <Text style={estilo.etiqueta}>AF Nº</Text>
                  </View>
                </View>

                <View style={estilo.infoRow}>
                  <View style={estilo.columna}>
                    <Text style={estilo.valor}>{obj.Parentesco || "Titular"}</Text>
                    <Text style={estilo.etiqueta}>Parentesco</Text>
                  </View>
                  <View style={estilo.columna}>
                    <Text style={estilo.valor}>{obj.Badocnumdo || "18.892.123"}</Text>
                    <Text style={estilo.etiqueta}>Documento</Text>
                  </View>
                  <View style={estilo.columna}>
                    <Text style={estilo.valor}>{obj.Plan || "Plan Azul"}</Text>
                    <Text style={estilo.etiqueta}>Categoría</Text>
                  </View>
                </View>
              </View>

              {/* Pie de tarjeta: Sellos a la izquierda y Firma a la derecha */}
              <View style={estilo.footer}>
                <Sellos />
                <FirmaText />
              </View>
            </View>
          </ImageBackground>
        </Animated.View>

        {/* --- CARA TRASERA (DORSO) --- */}
        <Animated.View
          style={[
            estilo.cardFace,
            estilo.cardFaceBack,
            {
              transform: [{ perspective: 1000 }, { rotateY: rotacionDorso }],
              opacity: opacidadDorso,
              backfaceVisibility: "hidden",
            },
          ]}
        >
          {/* Banda magnética simulada */}
          <View style={estilo.bandaMagnetica} />

          <View style={estilo.dorsoContent}>
            {/* Firma y Código de Seguridad */}
            <View style={estilo.dorsoRowSuperior}>
              <View style={estilo.dorsoFirmaBox}>
                <Text style={estilo.dorsoFirmaTexto}>
                  {obj.Apenom || "GUTIERREZ ROLDAN JEREMIAS"}
                </Text>
              </View>
              <View style={estilo.dorsoCodigoSeguridad}>
                <Text style={estilo.dorsoCvvLabel}>CÓDIGO SEG.</Text>
                <Text style={estilo.dorsoCvvValor}>942</Text>
              </View>
            </View>

            {/* Texto legal normativo */}
            <View style={estilo.dorsoInfoBox}>
              <Text style={estilo.dorsoLegal}>
                Esta credencial es personal e intransferible. El titular deberá
                presentar documento de identidad al momento de solicitar
                prestaciones médico-asistenciales. En caso de extravío, comuníquese
                de inmediato con la sede central de OSEM General Pueyrredon.
              </Text>
            </View>

            {/* Pie de Dorso: Teléfono de Urgencias y Web */}
            <View style={estilo.dorsoFooter}>
              <Text style={estilo.dorsoTelefono}>URGENCIAS: 0800-333-OSEM (6736)</Text>
              <Text style={estilo.dorsoWeb}>osem.org.ar</Text>
            </View>
          </View>
        </Animated.View>
      </TouchableOpacity>

      {/* Indicador interactivo para invitar a dar vuelta la tarjeta */}
      <TouchableOpacity
        style={flipStyles.botonGirarHint}
        onPress={voltearTarjeta}
        activeOpacity={0.8}
      >
        <MaterialCommunityIcons
          name="rotate-3d-variant"
          size={16}
          color="#38bdf8"
        />
        <Text style={flipStyles.textoGirarHint}>
          {esDorso ? "Tocar para ver el frente" : "Tocar para ver el dorso"}
        </Text>
      </TouchableOpacity>
    </View>
  );
}

const flipStyles = StyleSheet.create({
  contenedorPrincipal: {
    width: "100%",
    alignItems: "center",
  },
  botonGirarHint: {
    flexDirection: "row",
    alignItems: "center",
    gap: 6,
    marginTop: 10,
    paddingHorizontal: 12,
    paddingVertical: 5,
    borderRadius: 20,
    backgroundColor: "rgba(56, 189, 248, 0.1)",
    borderColor: "rgba(56, 189, 248, 0.25)",
    borderWidth: 1,
  },
  textoGirarHint: {
    fontSize: 11,
    fontWeight: "700",
    color: "#38bdf8",
    letterSpacing: 0.3,
  },
});
