import React from "react";
import { Platform } from "react-native";
import { createDrawerNavigator } from "@react-navigation/drawer";
import { ScreenAjustes } from "./Ajustes";
import { ScreenInicio } from "./Inicio";
import { CustomDrawer } from "../Componentes/CustomDrawer";
import { useAppTheme } from "../Theme";

const Drawer = createDrawerNavigator();

export function Main() {
  const { theme } = useAppTheme();

  return (
    <Drawer.Navigator
      drawerContent={(props) => <CustomDrawer {...props} />}
      screenOptions={{
        headerStyle: {
          backgroundColor: "transparent",
        },
        headerTintColor: theme.texto,
        headerTitleStyle: {
          fontWeight: "bold",
        },
        headerTransparent: true,
        headerTitle: "",
        headerStatusBarHeight: Platform.OS === "web" ? 48 : 20,
        drawerType: "front",
        drawerStyle: {
          width: 290,
          backgroundColor: theme.fondo,
        },
      }}
    >
      <Drawer.Screen name="ScreenInicio" component={ScreenInicio} />
      <Drawer.Screen name="ScreenAjustes" component={ScreenAjustes} />
    </Drawer.Navigator>
  );
}
