import React, { useState, useEffect } from "react";
import {
  View,
  Text,
  StyleSheet,
  Dimensions,
  Platform,
  TouchableOpacity,
} from "react-native";
import { Ionicons, Feather, MaterialCommunityIcons } from "@expo/vector-icons";

export function WebMobileFrame({ children }) {
  // Solo aplicamos el marco si estamos en plataforma web
  if (Platform.OS !== "web") {
    return <>{children}</>;
  }

  const [windowWidth, setWindowWidth] = useState(
    Dimensions.get("window").width
  );
  const [horaActual, setHoraActual] = useState("");
  const [modoMarco, setModoMarco] = useState(true);

  // Escuchar cambios de tamaño de pantalla en el navegador
  useEffect(() => {
    const updateDimensions = () => {
      setWindowWidth(Dimensions.get("window").width);
    };
    const subscription = Dimensions.addEventListener("change", updateDimensions);
    return () => {
      subscription?.remove ? subscription.remove() : null;
    };
  }, []);

  // Reloj simulado en tiempo real en la barra de estado
  useEffect(() => {
    const actualizarReloj = () => {
      const ahora = new Date();
      const horas = ahora.getHours().toString().padStart(2, "0");
      const minutos = ahora.getMinutes().toString().padStart(2, "0");
      setHoraActual(`${horas}:${minutos}`);
    };
    actualizarReloj();
    const interval = setInterval(actualizarReloj, 10000);
    return () => clearInterval(interval);
  }, []);

  // Si la pantalla es pequeña (ej: teléfono móvil real < 500px) o el usuario desactivó el marco
  const esPantallaPequena = windowWidth <= 520;

  if (esPantallaPequena || !modoMarco) {
    return (
      <View style={styles.pantallaCompleta}>
        {/* Si el usuario desactivó el marco manualmente en desktop, mostrar botón para reactivarlo */}
        {!esPantallaPequena && (
          <TouchableOpacity
            style={styles.botonReactivarMarco}
            onPress={() => setModoMarco(true)}
            activeOpacity={0.8}
          >
            <Feather name="smartphone" size={16} color="#ffffff" />
            <Text style={styles.textoBotonReactivar}>Ver con marco móvil</Text>
          </TouchableOpacity>
        )}
        {children}
      </View>
    );
  }

  return (
    <View style={styles.webBackdrop}>
      {/* Luz ambiental sutil detrás del dispositivo */}
      <View style={styles.luzFondo} />

      {/* Barra superior de presentación del Portafolio */}
      <View style={styles.portfolioHeader}>
        <View style={styles.headerInfo}>
          <View style={styles.badgeProyecto}>
            <View style={styles.dotOnline} />
            <Text style={styles.badgeTexto}>PORTFOLIO DEMO</Text>
          </View>
          <Text style={styles.tituloHeader}>OSEM • Credencial Digital</Text>
          <Text style={styles.subtituloHeader}>
            Simulador móvil interactivo para presentación en portafolio
          </Text>
        </View>

        <View style={styles.headerControles}>
          <TouchableOpacity
            style={styles.botonAlternar}
            onPress={() => setModoMarco(false)}
            activeOpacity={0.7}
          >
            <Feather name="maximize-2" size={15} color="#cbd5e1" />
            <Text style={styles.botonAlternarTexto}>Pantalla Completa</Text>
          </TouchableOpacity>
        </View>
      </View>

      {/* Marco de Smartphone Físico */}
      <View style={styles.dispositivoChasis}>
        {/* Botones físicos laterales (simulados en los costados) */}
        <View style={styles.botonVolumen1} />
        <View style={styles.botonVolumen2} />
        <View style={styles.botonEncendido} />

        {/* Pantalla del Teléfono */}
        <View style={styles.pantallaInterna}>
          {/* Barra de Estado Superior (Dynamic Island + Reloj + Indicadores) */}
          <View style={styles.statusBar}>
            <Text style={styles.statusHora}>{horaActual || "09:41"}</Text>

            {/* Dynamic Island con cámara y altavoz */}
            <View style={styles.dynamicIsland}>
              <View style={styles.camaraLente} />
              <View style={styles.sensorPunto} />
            </View>

            <View style={styles.statusIconos}>
              <Ionicons name="cellular" size={13} color="#ffffff" />
              <Ionicons name="wifi" size={13} color="#ffffff" />
              <Ionicons name="battery-full" size={16} color="#ffffff" />
            </View>
          </View>

          {/* Contenido real de la aplicación (Navegador y Vistas) */}
          <View style={styles.areaApp}>{children}</View>

          {/* Barra Home Indicator de iOS/Android moderno */}
          <View style={styles.homeIndicatorWrapper} pointerEvents="none">
            <View style={styles.homeIndicator} />
          </View>
        </View>
      </View>

      {/* Pie de la presentación */}
      <View style={styles.portfolioFooter}>
        <Text style={styles.footerInfoTexto}>
          Tip: Podés abrir el menú lateral tocando el ícono de las tres líneas en la esquina superior izquierda
        </Text>
      </View>
    </View>
  );
}

